import { DomainError } from "../domain/errors";
import { Order, OrderLine, OrderState } from "../domain/order";
import { OrderRepository, ProductRepository } from "../domain/repositories";
import { Product } from "../domain/product";

export interface PlaceOrderInput {
  customerId: string;
  items: readonly OrderLine[];
}

export interface ProductView {
  id: string;
  name: string;
  stock: number;
}

export interface OrderView {
  id: string;
  customerId: string;
  items: readonly OrderLine[];
  state: OrderState;
}

/** Coordinates the fulfilment use cases using domain repository abstractions. */
export class OrderService {
  public constructor(
    private readonly orders: OrderRepository,
    private readonly products: ProductRepository,
  ) {}

  public addProduct(id: string, name: string, stock: number): ProductView {
    if (this.products.findById(id)) throw new DomainError(`Product ${id} already exists`);
    const product = new Product(id, name, stock);
    this.products.save(product);
    return this.toProductView(product);
  }

  public placeOrder(input: PlaceOrderInput): OrderView {
    const id = crypto.randomUUID();
    const order = new Order(id, input.customerId, input.items.map((item) => ({ ...item })));
    const products = order.lines.map((line) => this.requiredProduct(line.productId));
    this.ensureStockIsAvailable(order.lines, products);
    order.lines.forEach((line, index) => products[index].reserve(line.quantity));
    products.forEach((product) => this.products.save(product));
    this.orders.save(order);
    return this.toOrderView(order);
  }

  public changeState(id: string, state: OrderState): OrderView {
    const order = this.requiredOrder(id);
    order.advanceTo(state);
    this.orders.save(order);
    return this.toOrderView(order);
  }

  public cancelOrder(id: string): OrderView {
    const order = this.requiredOrder(id);
    order.cancel();
    order.lines.forEach((line) => {
      const product = this.requiredProduct(line.productId);
      product.release(line.quantity);
      this.products.save(product);
    });
    this.orders.save(order);
    return this.toOrderView(order);
  }

  public listOrders(state?: OrderState): readonly OrderView[] {
    return this.orders.listByState(state).map((order) => this.toOrderView(order));
  }

  public listProducts(): readonly ProductView[] {
    return this.products.list().map((product) => this.toProductView(product));
  }

  private requiredProduct(id: string): Product {
    const product = this.products.findById(id);
    if (!product) throw new DomainError(`Product ${id} was not found`);
    return product;
  }

  private requiredOrder(id: string): Order {
    const order = this.orders.findById(id);
    if (!order) throw new DomainError(`Order ${id} was not found`);
    return order;
  }

  private ensureStockIsAvailable(lines: readonly OrderLine[], products: readonly Product[]): void {
    const requested = new Map<string, number>();
    lines.forEach((line) => requested.set(line.productId, (requested.get(line.productId) ?? 0) + line.quantity));
    requested.forEach((quantity, productId) => {
      const product = this.requiredProduct(productId);
      if (product.stock < quantity) throw new DomainError(`Insufficient stock for product ${productId}`);
    });
    void products;
  }

  private toProductView(product: Product): ProductView {
    return { id: product.id, name: product.name, stock: product.stock };
  }

  private toOrderView(order: Order): OrderView {
    return { id: order.id, customerId: order.customerId, items: order.lines.map((line) => ({ ...line })), state: order.state };
  }
}

